//! Generates the C header for this crate's `extern "C"` surface into
//! `OUT_DIR` — the PoC evidence for how much (or how little) cbindgen needs
//! hand-holding on quadraui's actual exported shapes (opaque structs,
//! `#[repr(C)]` vtables with function-pointer fields, `Option<fn(...)>`).
//!
//! This script never writes into the source tree: the checked-in
//! `include/quadraui_ffi.h` is a committed artifact, regenerated by hand
//! with `./generate-header.sh` when the `extern "C"` surface changes, and
//! kept honest by the `header_up_to_date` integration test in `tests/`
//! (which runs cbindgen itself and diffs the result against what's
//! committed).

use std::env;
use std::path::PathBuf;

fn main() {
    let crate_dir = env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR is set by cargo");
    let out_dir = env::var("OUT_DIR").expect("OUT_DIR is set by cargo");
    let out_path = PathBuf::from(out_dir).join("quadraui_ffi.h");

    // Keep this `Config` in sync with `tests/header_up_to_date.rs`'s copy:
    // `build.rs` isn't a library, so the two can't share one function.
    let config = cbindgen::Config {
        language: cbindgen::Language::C,
        pragma_once: true,
        ..cbindgen::Config::default()
    };

    match cbindgen::Builder::new()
        .with_crate(&crate_dir)
        .with_config(config)
        .generate()
    {
        Ok(bindings) => {
            bindings.write_to_file(&out_path);
        }
        Err(err) => {
            // A one-off cbindgen hiccup in this spike crate is evidence for
            // the toolchain write-up, not a reason to red every PR's CI: log
            // it loudly and keep the previously-generated (or checked-in)
            // header rather than failing the build.
            println!(
                "cargo::warning=cbindgen failed to generate {}: {err} (continuing without a fresh header)",
                out_path.display()
            );
        }
    }

    println!("cargo::rerun-if-changed=src/lib.rs");
    println!("cargo::rerun-if-changed=build.rs");
}
